package com.cdac.cssip.user.config; import com.cdac.cssip.common.security.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig{@Bean JwtTokenService jwt(@Value("${jwt.secret}")String s,@Value("${jwt.expiration}")long e){return new JwtTokenService(s,e);}@Bean JwtAuthenticationFilter filter(JwtTokenService j){return new JwtAuthenticationFilter(j);}@Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthenticationFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/internal/**","/h2-console/**").permitAll().anyRequest().authenticated()).headers(x->x.frameOptions(y->y.sameOrigin())).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}}
